import { type Base32Array } from "./lib/Base32.js";
import type { PublicKey } from "./Crypto.js";
import type { Flavor } from "./lib/utils/Flavor.js";
export type Fingerprint = Base32Array;
export type FingerprintDisplay = Flavor<string, "FingerprintDisplay">;
export declare const fromFingerprintDisplay: (fingerprintDisplay: FingerprintDisplay) => Fingerprint;
export declare const isFingerprint: (value: unknown) => value is Fingerprint;
export declare const uint8ArrayToFingerprint: (uint8Array: Uint8Array) => Promise<Fingerprint>;
export declare const publicKeyToFingerprint: (publicKey: PublicKey) => Promise<Fingerprint>;
export declare const idToFingerprint: (id: string) => Promise<Fingerprint>;
export declare const fingerprintToUint8Array: (fingerprint: Fingerprint) => Uint8Array;
export declare const getFingerprintLength: (fingerprint: Fingerprint) => number;
export declare const getFingerprintDisplayLength: (fingerprintDisplay: FingerprintDisplay) => number;
export declare const compareFingerprints: (a: Fingerprint, b: Fingerprint) => boolean;
export declare const fingerprintStartsWith: (fingerprint: Fingerprint, partialFingerprint: Fingerprint) => boolean;
export declare const fingerprintDisplayStartsWith: (fingerprintDisplay: FingerprintDisplay, partialFingerprintDisplay: FingerprintDisplay) => boolean;
export declare const sliceFingerprint: (fingerprint: Fingerprint, length?: number) => Fingerprint;
